#!/usr/bin/env python3
"""Build the offline manual and console using only Python's standard library.

The markdown renderer covers this manual's headings, fenced code, links, lists,
paragraphs and tables. Exact chart SVG is shipped; use build_charts.py to redraw.
"""
from pathlib import Path
import collections, html, json, math, re
ROOT=Path(__file__).resolve().parent
H=html.escape

def inline(s):
    held=[]
    def keep(v):held.append(v);return f'ZZTOKEN{len(held)-1}ZZ'
    s=re.sub(r'`([^`]+)`',lambda m:keep('<code>'+H(m[1])+'</code>'),s)
    s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',lambda m:keep('<a href="'+H(m[2],quote=True)+'">'+H(m[1])+'</a>'),s)
    s=H(s)
    s=re.sub(r'\*\*(.+?)\*\*',r'<strong>\1</strong>',s)
    for i,v in enumerate(held):s=s.replace(f'ZZTOKEN{i}ZZ',v)
    return s

def slug(s):return re.sub('[^a-z0-9]+','-',s.lower()).strip('-')

def markdown(s):
    lines=s.splitlines();out=[];toc=[];i=0
    while i<len(lines):
        line=lines[i]
        if not line.strip():i+=1;continue
        if line.startswith('<!--'):
            out.append(line);i+=1;continue
        if line.startswith('```'):
            kind=line[3:];code=[];i+=1
            while i<len(lines) and not lines[i].startswith('```'):code.append(lines[i]);i+=1
            out.append('<pre class="'+('equation' if kind=='text' else 'codeblock')+'"><code>'+H('\n'.join(code))+'</code></pre>');i+=1;continue
        if line.startswith('#'):
            marks,title=line.split(' ',1);lev=len(marks);sid=slug(title)
            if lev==2:toc.append((sid,title))
            out.append(f'<h{lev} id="{sid}">{inline(title)}</h{lev}>');i+=1;continue
        if line.startswith('|'):
            rows=[]
            while i<len(lines) and lines[i].startswith('|'):
                cells=[v.strip() for v in lines[i].strip().strip('|').split('|')]
                if not all(re.fullmatch(r':?-+:?',v or ' ') for v in cells):rows.append(cells)
                i+=1
            out.append('<div class="tablewrap"><table><thead><tr>'+''.join('<th>'+inline(c)+'</th>' for c in rows[0])+'</tr></thead><tbody>')
            out.extend('<tr>'+''.join('<td>'+inline(c)+'</td>' for c in row)+'</tr>' for row in rows[1:])
            out.append('</tbody></table></div>');continue
        if line.startswith('- '):
            out.append('<ul>')
            while i<len(lines) and lines[i].startswith('- '):out.append('<li>'+inline(lines[i][2:])+'</li>');i+=1
            out.append('</ul>');continue
        para=[line];i+=1
        while i<len(lines) and lines[i].strip() and not lines[i].startswith(('#','```','|','<!--','- ')):
            para.append(lines[i]);i+=1
        out.append('<p>'+inline(' '.join(para))+'</p>')
    return '\n'.join(out),toc

